/**
 * File storage for photos, voice notes and documents.
 *
 * Two drivers, chosen by STORAGE_DRIVER:
 *  - "local" (default): files under STORAGE_LOCAL_DIR (default ./storage) on the
 *    app server's disk. Good for development and a single self-hosted server.
 *  - "s3": any S3-compatible service (Hetzner Object Storage, MinIO, AWS S3, …),
 *    configured with S3_ENDPOINT, S3_REGION, S3_BUCKET, S3_ACCESS_KEY_ID,
 *    S3_SECRET_ACCESS_KEY and optionally S3_FORCE_PATH_STYLE=true.
 *
 * Server-only. Keys are generated by the app (see media.ts), never taken from
 * a client, and are validated again here before touching the disk or bucket.
 */
import { Buffer } from 'node:buffer';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';

export interface StoredObject {
  body: Buffer;
  contentType: string;
}

export interface StorageDriver {
  readonly name: 'local' | 's3';
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<StoredObject | null>;
  delete(key: string): Promise<void>;
  /** A short-lived URL the client can fetch directly, or null if the driver serves bytes itself. */
  signedUrl(key: string, ttlSeconds: number, downloadName?: string): Promise<string | null>;
}

const KEY_RE = /^[a-zA-Z0-9_-]+(\/[a-zA-Z0-9_-]+)*\.[a-z0-9]{1,5}$/;

export function assertStorageKey(key: string): string {
  if (!KEY_RE.test(key) || key.includes('..')) throw new Error(`Invalid storage key: ${key}`);
  return key;
}

class LocalDriver implements StorageDriver {
  readonly name = 'local' as const;
  private readonly root: string;

  constructor(root: string) {
    this.root = resolve(root);
  }

  private path(key: string) {
    const full = resolve(join(this.root, assertStorageKey(key)));
    if (!full.startsWith(this.root + '/')) throw new Error(`Invalid storage key: ${key}`);
    return full;
  }

  async put(key: string, body: Buffer, contentType: string) {
    const full = this.path(key);
    await mkdir(dirname(full), { recursive: true });
    await writeFile(full, body);
    await writeFile(`${full}.type`, contentType);
  }

  async get(key: string) {
    const full = this.path(key);
    try {
      const [body, contentType] = await Promise.all([
        readFile(full),
        readFile(`${full}.type`, 'utf8').catch(() => 'application/octet-stream'),
      ]);
      return { body, contentType };
    } catch (error) {
      if ((error as { code?: string }).code === 'ENOENT') return null;
      throw error;
    }
  }

  async delete(key: string) {
    const full = this.path(key);
    await rm(full, { force: true });
    await rm(`${full}.type`, { force: true });
  }

  async signedUrl() {
    return null;
  }
}

class S3Driver implements StorageDriver {
  readonly name = 's3' as const;
  private clientPromise: Promise<import('@aws-sdk/client-s3').S3Client> | null = null;

  constructor(private readonly bucket: string) {}

  private client() {
    this.clientPromise ??= import('@aws-sdk/client-s3').then(({ S3Client }) => new S3Client({
      endpoint: process.env.S3_ENDPOINT || undefined,
      region: process.env.S3_REGION || 'eu-central-1',
      forcePathStyle: process.env.S3_FORCE_PATH_STYLE === 'true',
      credentials: {
        accessKeyId: required('S3_ACCESS_KEY_ID'),
        secretAccessKey: required('S3_SECRET_ACCESS_KEY'),
      },
    }));
    return this.clientPromise;
  }

  async put(key: string, body: Buffer, contentType: string) {
    const { PutObjectCommand } = await import('@aws-sdk/client-s3');
    await (await this.client()).send(new PutObjectCommand({
      Bucket: this.bucket,
      Key: assertStorageKey(key),
      Body: body,
      ContentType: contentType,
    }));
  }

  async get(key: string) {
    const { GetObjectCommand, NoSuchKey } = await import('@aws-sdk/client-s3');
    try {
      const res = await (await this.client()).send(new GetObjectCommand({ Bucket: this.bucket, Key: assertStorageKey(key) }));
      const bytes = await res.Body?.transformToByteArray();
      if (!bytes) return null;
      return { body: Buffer.from(bytes), contentType: res.ContentType ?? 'application/octet-stream' };
    } catch (error) {
      if (error instanceof NoSuchKey) return null;
      throw error;
    }
  }

  async delete(key: string) {
    const { DeleteObjectCommand } = await import('@aws-sdk/client-s3');
    await (await this.client()).send(new DeleteObjectCommand({ Bucket: this.bucket, Key: assertStorageKey(key) }));
  }

  async signedUrl(key: string, ttlSeconds: number, downloadName?: string) {
    const [{ GetObjectCommand }, { getSignedUrl }] = await Promise.all([
      import('@aws-sdk/client-s3'),
      import('@aws-sdk/s3-request-presigner'),
    ]);
    const command = new GetObjectCommand({
      Bucket: this.bucket,
      Key: assertStorageKey(key),
      ResponseContentDisposition: downloadName ? `attachment; filename="${downloadName}"` : 'inline',
    });
    return getSignedUrl(await this.client(), command, { expiresIn: ttlSeconds });
  }
}

function required(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is not set (required for STORAGE_DRIVER=s3)`);
  return value;
}

declare global {
  // eslint-disable-next-line no-var
  var __storage: StorageDriver | undefined;
}

export function getStorage(): StorageDriver {
  if (globalThis.__storage) return globalThis.__storage;
  const driver = (process.env.STORAGE_DRIVER || 'local').toLowerCase();
  if (driver === 's3') {
    globalThis.__storage = new S3Driver(required('S3_BUCKET'));
  } else if (driver === 'local') {
    globalThis.__storage = new LocalDriver(process.env.STORAGE_LOCAL_DIR || join(process.cwd(), 'storage'));
  } else {
    throw new Error(`Unknown STORAGE_DRIVER "${driver}" (use "local" or "s3")`);
  }
  return globalThis.__storage;
}

/** Test hook: drop the cached driver so the next getStorage() re-reads the environment. */
export function resetStorageForTests() {
  globalThis.__storage = undefined;
}
